/** Federal part of the combined rate, for countries that have one. */
const FEDERAL_RATES: Record<string, number> = { CA: 0.05 };

/**
 * `taxRateFor` split into federal and regional fractions that add up to it.
 * Anything without a federal part (the US, unknown regions) is all regional.
 */
export function taxComponentsFor(
  address: Address,
  taxClass: TaxClass,
  fallback: number,
): { federal: number; regional: number } {
  const total = taxRateFor(address, taxClass, fallback);
  const country = address.country.toUpperCase();
  const known = RATES[country]?.[address.region.toUpperCase()] !== undefined;
  const share = taxClass === 'reduced' ? REDUCED_SHARE : 1;
  const federal = known ? Math.min(FEDERAL_RATES[country] ?? 0, total / share) * share : 0;
  // Rounded so that e.g. 0.13 - 0.05 gives 0.08 rather than 0.08000000000000002.
  return { federal, regional: Math.round((total - federal) * 1e9) / 1e9 };
}
